      </div>
    );
  }

  const values = chartData.map((d) => d.value);
  const dataMin = Math.min(...values);
  const dataMax = Math.max(...values);
  const yMin = Math.min(dataMin, refMin ?? dataMin);
  const yMax = Math.max(dataMax, refMax ?? dataMax);
  const pad = (yMax - yMin || 1) * 0.2;

  const lastIndex = chartData.length - 1;

  const renderValueLabel = (props: {
    x?: number | string;
    y?: number | string;
    value?: number | string;
    index?: number;
  }) => {
    const x = Number(props.x);
    const y = Number(props.y);
    if (isNaN(x) || isNaN(y)) return null;

    if (props.index === lastIndex) {
      return (
        <g>
          <text x={x + 14} y={y - 4} fontSize={11} fill="#6b7280">
            {t("latest")}
          </text>
          <text
            x={x + 14}
            y={y + 13}
            fontSize={15}
            fontWeight={600}
            fill="#111827"
          >
            {props.value}
          </text>
        </g>
      );
    }

    return (
      <text
        x={x}
        y={y - 12}
        textAnchor="middle"
        fontSize={12}
        fill="#374151"
      >
        {props.value}
      </text>
    );
  };

  return (
    <div className="relative mt-4" style={{ height: 320 }}>
      <div className="pointer-events-none absolute left-3 top-1 z-10 text-xs text-gray-500">
        ({t("ref")} {refMin ?? "-"}-{refMax ?? "-"} {unit})
      </div>
      <div className="pointer-events-none absolute right-4 top-1 z-10 text-xs text-gray-500">
        {t("newest")} →
      </div>
      <ResponsiveContainer width="100%" height="100%">
        <LineChart
          data={chartData}
          margin={{ top: 32, right: 72, left: 8, bottom: 8 }}
        >
          {refMin !== undefined && refMax !== undefined && (
            <ReferenceArea
              y1={refMin}
              y2={refMax}
              fill="#dbeafe"
              fillOpacity={0.5}
              stroke="none"
              ifOverflow="extendDomain"
            />
          )}
          <XAxis
            dataKey="time"
            type="number"
            scale="time"
            domain={["dataMin", "dataMax"]}
            tickFormatter={(value) =>
              isToday(new Date(value))
                ? t("today")
                : format(new Date(value), "d MMM")
            }
            tickLine={false}
            axisLine={false}
            tick={{ fontSize: 12, fill: "#6b7280" }}
            padding={{ left: 20, right: 20 }}
          />
          <YAxis hide domain={[yMin - pad, yMax + pad]} />
          <Line
            type="monotone"
            dataKey="value"
            stroke="#9ca3af"
            strokeWidth={1.5}
            dot={{ r: 4, fill: "#16a34a", stroke: "#16a34a" }}
            activeDot={{ r: 5, fill: "#16a34a" }}
            isAnimationActive={false}
          >
            <LabelList dataKey="value" content={renderValueLabel} />
          </Line>
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};
