      if (result.effective_datetime) {
        daySet.add(format(new Date(result.effective_datetime), "yyyy-MM-dd"));
      }
    }
  }

  // Most recent day first.
  const days = Array.from(daySet).sort(
    (a, b) => new Date(b).getTime() - new Date(a).getTime(),
