        if (refMax != null && numeric > refMax) direction = "up";
        else if (refMin != null && numeric < refMin) direction = "down";
      }

      valuesByDay.set(day, {
        time,
        value: result.value?.value,
        abnormal,
        direction,
      });
    }

    const hasAbnormal = Array.from(valuesByDay.values()).some(
