              : t("showing_all_readings", { count: days.length })}
          </p>
        </div>
        <label className="flex cursor-pointer items-center gap-2 whitespace-nowrap text-sm font-medium text-gray-700">
          <Switch checked={abnormalOnly} onCheckedChange={setAbnormalOnly} />
          {t("abnormal_only")}
        </label>
        <div className="flex items-center gap-1">
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => scrollBy(-240)}
            aria-label={t("scroll_left")}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => scrollBy(240)}
            aria-label={t("scroll_right")}
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
      </div>

      {/* Table */}
      <div ref={scrollRef} className="overflow-x-auto border-t border-gray-200">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-50 hover:bg-gray-50">
              <TableHead
                className={cn(stickyColClass, "bg-gray-50 text-gray-600")}
              >
                {t("component")}
              </TableHead>
              {days.map((day) => {
                const isTodayCol = day === todayDay;
                return (
                  <TableHead
                    key={day}
                    className={cn(
                      "whitespace-nowrap text-center font-normal text-gray-600",
                      isTodayCol &&
                        "sticky left-64 z-20 bg-primary-50 text-primary-700 border-x border-primary-100",
                    )}
                  >
                    {isTodayCol ? (
                      <span className="inline-flex items-center gap-1 font-medium">
                        <Pin className="size-3 fill-current" />
                        {t("today")}
                      </span>
                    ) : (
                      format(new Date(day), "d MMM")
                    )}
                  </TableHead>
                );
              })}
            </TableRow>
          </TableHeader>
          <TableBody>
            {visibleRows.map((row) => (
              <TableRow key={row.id} className="hover:bg-transparent">
                <TableCell className={cn(stickyColClass, "bg-white")}>
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="font-semibold text-gray-950">
                      {row.title}
                    </span>
                    {(row.refMin != null || row.refMax != null) && (
                      <span className="whitespace-nowrap text-xs text-gray-500">
                        ({row.refMin ?? "-"} &ndash; {row.refMax ?? "-"}
                        {row.unit ? ` ${row.unit}` : ""})
                      </span>
                    )}
                  </div>
                </TableCell>
                {days.map((day) => {
                  const entry = row.valuesByDay.get(day);
                  const isTodayCol = day === todayDay;
                  return (
                    <TableCell
                      key={day}
                      className={cn(
                        "whitespace-nowrap text-center",
                        isTodayCol &&
                          "sticky left-64 z-10 border-x border-primary-100 bg-primary-50/60",
                        entry?.abnormal &&
                          "bg-orange-100 font-medium text-orange-700",
                      )}
                    >
                      <span className="inline-flex items-center gap-1">
                        {entry?.value ?? "-"}
                        {entry?.abnormal && entry.direction === "up" && (
                          <ArrowUpRight className="size-3.5" />
