      (entry) => entry.abnormal,
    );

    return {
      id: obs.id,
      title: obs.observation_definition?.title || t("observation"),
      unit,
      refMin,
      refMax,
      valuesByDay,
      hasAbnormal,
    };
  });

  const visibleRows = abnormalOnly
    ? rows.filter((row) => row.hasAbnormal)
    : rows;

  const stickyColClass =
    "sticky left-0 z-20 w-64 min-w-64 max-w-64 border-r border-gray-200";

  return (
    <div className="overflow-hidden rounded-xl border border-gray-200 bg-white">
      {/* Heading */}
      <div className="flex items-center gap-3 border-l-4 border-l-primary-600 p-4">
        <div className="min-w-0 flex-1">
          <h3 className="truncate text-base font-semibold text-gray-950">
            {title}{" "}
            <span className="font-normal text-gray-500">
              ({t("recordings_count", { count: days.length })})
            </span>
          </h3>
          <p className="text-sm text-gray-500">
            {abnormalOnly
              ? t("showing_abnormal_readings")
              : t("showing_all_readings", { count: days.length })}
          </p>
        </div>
        <label className="flex cursor-pointer items-center gap-2 whitespace-nowrap text-sm font-medium text-gray-700">
          <Switch checked={abnormalOnly} onCheckedChange={setAbnormalOnly} />
          {t("abnormal_only")}
        </label>
        <div className="flex items-center gap-1">
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => scrollBy(-240)}
            aria-label={t("scroll_left")}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => scrollBy(240)}
            aria-label={t("scroll_right")}
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
      </div>

      {/* Table */}
      <div ref={scrollRef} className="overflow-x-auto border-t border-gray-200">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-50 hover:bg-gray-50">
              <TableHead
                className={cn(stickyColClass, "bg-gray-50 text-gray-600")}
              >
                {t("component")}
              </TableHead>
              {days.map((day) => {
                const isTodayCol = day === todayDay;
                return (
                  <TableHead
                    key={day}
                    className={cn(
                      "whitespace-nowrap text-center font-normal text-gray-600",
                      isTodayCol &&
                        "sticky left-64 z-20 bg-primary-50 text-primary-700 border-x border-primary-100",
                    )}
                  >
                    {isTodayCol ? (
                      <span className="inline-flex items-center gap-1 font-medium">
                        <Pin className="size-3 fill-current" />
                        {t("today")}
                      </span>
                    ) : (
                      format(new Date(day), "d MMM")
                    )}
                  </TableHead>
                );
              })}
            </TableRow>
          </TableHeader>
          <TableBody>
            {visibleRows.map((row) => (
              <TableRow key={row.id} className="hover:bg-transparent">
                <TableCell className={cn(stickyColClass, "bg-white")}>
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="font-semibold text-gray-950">
                      {row.title}
                    </span>
                    {(row.refMin != null || row.refMax != null) && (
                      <span className="whitespace-nowrap text-xs text-gray-500">
                        ({row.refMin ?? "-"} &ndash; {row.refMax ?? "-"}
                        {row.unit ? ` ${row.unit}` : ""})
                      </span>
                    )}
                  </div>
                </TableCell>
                {days.map((day) => {
                  const entry = row.valuesByDay.get(day);
                  const isTodayCol = day === todayDay;
                  return (
                    <TableCell
                      key={day}
                      className={cn(
                        "whitespace-nowrap text-center",
                        isTodayCol &&
                          "sticky left-64 z-10 border-x border-primary-100 bg-primary-50/60",
                        entry?.abnormal &&
                          "bg-orange-100 font-medium text-orange-700",
                      )}
                    >
                      <span className="inline-flex items-center gap-1">
                        {entry?.value ?? "-"}
                        {entry?.abnormal && entry.direction === "up" && (
                          <ArrowUpRight className="size-3.5" />
                        )}
                        {entry?.abnormal && entry.direction === "down" && (
                          <ArrowDownRight className="size-3.5" />
                        )}
                      </span>
                    </TableCell>
                  );
                })}
              </TableRow>
            ))}
            {visibleRows.length === 0 && (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={days.length + 1}
                  className="h-24 text-center text-sm text-gray-500"
                >
                  {t("no_abnormal_readings")}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
};

arguments.oldString:
const ObservationHistoryTable = ({
  observations,
  patientId,
  encounterId,
}: {
  observations: ObservationRead[];
  patientId: string;
  encounterId: string;
}) => {
  const { t } = useTranslation();

  const codes = observations
    .map((obs) => obs.main_code)
    .filter((code): code is NonNullable<typeof code> => code != null);

  const { data, isLoading } = useQuery({
    queryKey: [
      "observations-table",
      patientId,
      encounterId,
      codes.map((c) => c.code),
    ],
    queryFn: query(observationApi.analyse, {
      pathParams: { patientId },
      queryParams: { encounter: encounterId },
      body: { codes },
    }),
    enabled: codes.length > 0,
  });

  if (isLoading || !data) {
    return <Loading />;
  }

  // Collect all unique calendar days across all observation groups.
  const daySet = new Set<string>();
  for (const group of data.results) {
    for (const result of group.results) {
      if (result.effective_datetime) {
        daySet.add(format(new Date(result.effective_datetime), "yyyy-MM-dd"));
      }
    }
  }

  // Most recent day first.
  const days = Array.from(daySet).sort(
    (a, b) => new Date(b).getTime() - new Date(a).getTime(),
  );

  if (days.length === 0) {
    return (
      <div className="flex h-24 items-center justify-center text-sm text-gray-500">
        {t("no_data_available")}
      </div>
    );
  }

  const rows = observations.map((obs) => {
    const group = data.results.find(
      (rg) => rg.code.code === obs.main_code?.code,
    );

    // For each day keep the latest reading of that day.
    const valuesByDay = new Map<
      string,
      {
        time: number;
        value?: string | null;
        interpretation?: Interpretation;
      }
    >();
    for (const result of group?.results ?? []) {
      if (!result.effective_datetime) continue;
      const time = new Date(result.effective_datetime).getTime();
      const day = format(new Date(result.effective_datetime), "yyyy-MM-dd");
      const existing = valuesByDay.get(day);
      if (!existing || time > existing.time) {
        valuesByDay.set(day, {
          time,
          value: result.value?.value,
          interpretation: result.interpretation,
        });
      }
    }

    const unit = obs.value?.unit?.display || obs.value?.unit?.code || "";
    const refRange = obs.reference_range?.[0];

    return {
      id: obs.id,
      title: obs.observation_definition?.title || t("observation"),
      unit,
      refMin: refRange?.min,
      refMax: refRange?.max,
      valuesByDay,
    };
  });

  return (
    <div className="overflow-x-auto rounded-lg border">
      <Table>
        <TableHeader>
          <TableRow className="bg-gray-50">
            <TableHead className="sticky left-0 z-10 bg-gray-50">
              {t("component")}
            </TableHead>
            {days.map((day) => (
              <TableHead
                key={day}
                className="whitespace-nowrap text-center font-normal"
              >
                {isToday(new Date(day))
                  ? t("today")
                  : format(new Date(day), "d MMM")}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.id}>
              <TableCell className="sticky left-0 z-10 bg-white">
                <div className="font-medium">{row.title}</div>
                {(row.refMin != null || row.refMax != null) && (
                  <div className="text-xs text-gray-500">
                    ({row.refMin ?? "-"} - {row.refMax ?? "-"}
                    {row.unit ? ` ${row.unit}` : ""})
                  </div>
                )}
              </TableCell>
              {days.map((day) => {
                const entry = row.valuesByDay.get(day);
                const highlight = entry?.interpretation?.highlight;
                return (
                  <TableCell
                    key={day}
                    className={cn(
                      "whitespace-nowrap text-center",
                      highlight && "bg-orange-50 font-medium text-orange-700",
                    )}
                  >
                    {entry?.value ?? "-"}
                  </TableCell>
                );
              })}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
};

