import {
  useIsMutating,
  useMutation,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";

const CLASSIFICATIONS_CAN_BE_MARKED_AS_COMPLETE = [
  Classification.surgical_procedure,
  Classification.counselling,
]; // TODO: Procedure won’t be in this list, so remove this variable and directly check for the AD slug instead

// Shared key so the parent can observe the completion mutation's pending state
// (owned by CompletionNoteContent) without re-declaring the mutation.
const completeServiceRequestMutationKey = (serviceRequestId: string) => [
  "completeServiceRequest",
  serviceRequestId,
];

const [isCompleteDialogOpen, setIsCompleteDialogOpen] = useState(false);
const [selectedSpecimenDefinition, setSelectedSpecimenDefinition] =
  useState<SpecimenDefinitionRead | null>(null);

// Prevent dismissing the completion dialog while its mutation is in flight.
const isCompletingServiceRequest =
  useIsMutating({
    mutationKey: completeServiceRequestMutationKey(serviceRequestId),
  }) > 0;

